SELECT id, document_id, document_name, library_id, parent_id, document_type, content_source, revision, word_count, view_count, is_convert, is_builtin, builtin_type, prev_document_id, tenant_id, creator_id, updator_id, created_time, updated_time, status_cd, file_info_id, permission_mode, space_id FROM bt_dc_document WHERE library_id = #{libraryId} AND document_type = 'ROOT' and status_cd = '00A'
AND (tenant_id = #{tenantId} or is_builtin='T')
AND space_id = #{spaceId}

SELECT bdd.document_id as node_id, bdd.library_id, bdd.creator_id, CASE WHEN bdd.parent_id = '0' THEN bddl.library_name ELSE bdd.document_name END AS node_name, bdd.document_type as node_type, bdd.content_source, bdd.parent_id, bdd.tenant_id, bdd.space_id, bdd.prev_document_id as pre_node_id, CASE WHEN EXISTS ( SELECT 1 FROM bt_dc_document leaf WHERE leaf.parent_id = bdd.document_id AND leaf.status_cd = '00A' ) THEN 1 ELSE 0 END AS has_children, bdd.created_time, bdd.updated_time, CASE WHEN EXISTS ( SELECT 1 FROM bt_dc_document_permission ddp WHERE ddp.document_id = bdd.document_id AND ddp.status_cd = '00A' ) THEN 1 ELSE 0 END as node_permit_set, CASE WHEN duf.target_id IS NOT NULL THEN 1 ELSE 0 END AS node_favorite, CASE WHEN bduhp.target_id IS NOT NULL THEN 1 ELSE 0 END AS node_pined FROM bt_dc_document bdd JOIN bt_dc_document_library bddl ON bdd.library_id = bddl.library_id LEFT JOIN bt_dc_user_favorite duf ON duf.target_id = bdd.document_id AND duf.target_type IN ('DOCUMENT', 'FOLDER') AND duf.user_id = #{userId} AND duf.status_cd = '00A' AND duf.tenant_id = #{query.envTenantId} LEFT JOIN bt_dc_user_homepage_pin bduhp ON bduhp.target_id = bdd.document_id AND bduhp.target_type = 'DOCUMENT' AND bduhp.user_id = #{userId} AND bduhp.status_cd = '00A' AND bduhp.tenant_id = #{query.envTenantId} WHERE bdd.parent_id = #{query.documentId} AND bdd.status_cd = '00A'
AND bdd.tenant_id = #{query.tenantId}
AND bdd.document_name LIKE #{keywordPattern}
ORDER BY bdd.created_time DESC
